# >>> CHOICES
_choice_agent() {
    NO_COLOR=1 skills list -a __argc_invalid__ 2>&1 \
        | gawk '/Valid agents: / {
            sub(/.*Valid agents: /, "")
            n = split($0, a, /, */)
            for (i = 1; i <= n; i++) print a[i]
        }'
    printf '%s\n' '*'
}

_choice_installed_skill() {
    skills list --json 2>/dev/null | jq -b -r '.[] | "\(.name)\t\(.scope) \(.status)"'
    skills list -g --json 2>/dev/null | jq -b -r '.[] | "\(.name)\t\(.scope) \(.status)"'
}
